#!/usr/bin/env python3
"""Patch the Android files generated by `flutter create` for Rafiq.

- Injects RECORD_AUDIO and MODIFY_AUDIO_SETTINGS permissions before <application>.
- Adds android:largeHeap="true" to the <application> tag.
- Adds notification permissions (POST_NOTIFICATIONS, RECEIVE_BOOT_COMPLETED, VIBRATE).
- Sets the launcher label to "رَفِيق".
- Raises minSdk to at least 24 and compileSdk to at least 35 (never lowers them),
  in both build.gradle.kts and build.gradle.
- Enables core library desugaring (required by flutter_local_notifications).
- Copies scripts/android_res/* (launcher icons, adaptive icon, notification icon)
  into android/app/src/main/res/.

The script is idempotent: running it twice changes nothing the second time.
"""

import pathlib
import re
import shutil
import sys

MANIFEST = pathlib.Path("android/app/src/main/AndroidManifest.xml")
GRADLE_FILES = (
    pathlib.Path("android/app/build.gradle.kts"),
    pathlib.Path("android/app/build.gradle"),
)

PERMISSIONS = (
    "android.permission.RECORD_AUDIO",
    "android.permission.MODIFY_AUDIO_SETTINGS",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.RECEIVE_BOOT_COMPLETED",
    "android.permission.VIBRATE",
)

APP_LABEL = "رَفِيق"
RES_SRC = pathlib.Path("scripts/android_res")
RES_DST = pathlib.Path("android/app/src/main/res")
DESUGAR_LIB = "com.android.tools:desugar_jdk_libs:2.1.4"

MIN_SDK = 24
COMPILE_SDK = 35


def patch_manifest(text: str) -> str:
    # 1) permissions, placed right before the <application> tag
    app_match = re.search(r"^([ \t]*)<application\b", text, re.MULTILINE)
    if app_match is None:
        raise RuntimeError("<application> tag not found in AndroidManifest.xml")
    indent = app_match.group(1)
    missing = [p for p in PERMISSIONS if p not in text]
    if missing:
        block = "".join(
            '{0}<uses-permission android:name="{1}" />\n'.format(indent, p)
            for p in missing
        )
        text = text[: app_match.start()] + block + text[app_match.start():]

    # 2) largeHeap on the <application> tag
    tag_match = re.search(r"<application\b[^>]*>", text, re.DOTALL)
    if tag_match is None:
        raise RuntimeError("<application> tag not found after permission injection")
    tag = tag_match.group(0)
    new_tag = tag
    if "android:largeHeap" not in new_tag:
        new_tag = new_tag.replace("<application", '<application android:largeHeap="true"', 1)
    new_tag = re.sub(r'android:label="[^"]*"', 'android:label="{0}"'.format(APP_LABEL), new_tag, count=1)
    if new_tag != tag:
        text = text[: tag_match.start()] + new_tag + text[tag_match.end():]
    return text


def _raise_number(match, minimum):
    value = int(match.group("num"))
    return match.group("head") + str(max(value, minimum)) + match.group("tail")


def patch_gradle(text: str, is_kts: bool):
    """Returns (new_text, list_of_changes)."""
    changes = []

    def sub(pattern, repl, label):
        nonlocal text
        new_text, count = re.subn(pattern, repl, text)
        if count:
            changes.append(label)
            text = new_text

    if is_kts:
        sub(r"minSdk\s*=\s*flutter\.minSdkVersion",
            "minSdk = maxOf(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdk (flutter.minSdkVersion -> >= {0})".format(MIN_SDK))
        sub(r"compileSdk\s*=\s*flutter\.compileSdkVersion",
            "compileSdk = maxOf(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdk (flutter.compileSdkVersion -> >= {0})".format(COMPILE_SDK))
        sub(r"minSdkVersion\s*=\s*flutter\.minSdkVersion",
            "minSdkVersion = maxOf(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdkVersion (kts)")
        sub(r"compileSdkVersion\s*=\s*flutter\.compileSdkVersion",
            "compileSdkVersion = maxOf(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdkVersion (kts)")
        pat_min = r"(?P<head>\bminSdk(?:Version)?\s*=\s*)(?P<num>\d+)(?P<tail>)"
        pat_compile = r"(?P<head>\bcompileSdk(?:Version)?\s*=\s*)(?P<num>\d+)(?P<tail>)"
    else:
        sub(r"minSdkVersion\s+flutter\.minSdkVersion",
            "minSdkVersion Math.max(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdkVersion (flutter.minSdkVersion -> >= {0})".format(MIN_SDK))
        sub(r"compileSdkVersion\s+flutter\.compileSdkVersion",
            "compileSdkVersion Math.max(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdkVersion (flutter.compileSdkVersion -> >= {0})".format(COMPILE_SDK))
        sub(r"minSdk\s+flutter\.minSdkVersion",
            "minSdk Math.max(flutter.minSdkVersion, {0})".format(MIN_SDK),
            "minSdk (groovy)")
        sub(r"compileSdk\s+flutter\.compileSdkVersion",
            "compileSdk Math.max(flutter.compileSdkVersion, {0})".format(COMPILE_SDK),
            "compileSdk (groovy)")
        pat_min = r"(?P<head>\bminSdk(?:Version)?[ \t]+)(?P<num>\d+)(?P<tail>)"
        pat_compile = r"(?P<head>\bcompileSdk(?:Version)?[ \t]+)(?P<num>\d+)(?P<tail>)"

    # literal numbers: raise only when lower than the target
    before = text
    text = re.sub(pat_min, lambda m: _raise_number(m, MIN_SDK), text)
    text = re.sub(pat_compile, lambda m: _raise_number(m, COMPILE_SDK), text)
    if text != before:
        changes.append("numeric minSdk/compileSdk raised")
    return text, changes


def enable_desugaring(text: str, is_kts: bool):
    """Appends a second `android { compileOptions { ... } }` block plus the
    desugaring dependency. Appending avoids depending on how the generated
    template is laid out. Returns (new_text, changed)."""
    changed = False
    flag_present = "isCoreLibraryDesugaringEnabled = true" in text or (
        "coreLibraryDesugaringEnabled true" in text
    )
    if not flag_present:
        if is_kts:
            block = "\n\nandroid {\n    compileOptions {\n        isCoreLibraryDesugaringEnabled = true\n    }\n}\n"
        else:
            block = "\n\nandroid {\n    compileOptions {\n        coreLibraryDesugaringEnabled true\n    }\n}\n"
        text = text.rstrip() + block
        changed = True
    dependency_present = DESUGAR_LIB in text
    if not dependency_present:
        if is_kts:
            text = text.rstrip() + '\n\ndependencies {\n    coreLibraryDesugaring("' + DESUGAR_LIB + '")\n}\n'
        else:
            text = text.rstrip() + "\n\ndependencies {\n    coreLibraryDesugaring '" + DESUGAR_LIB + "'\n}\n"
        changed = True
    return text, changed



def configure_release_signing(text: str, is_kts: bool):
    """Use a repository-secret keystore when configured, retaining a debug fallback."""
    if is_kts:
        block = '''    if (!System.getenv("RELEASE_KEYSTORE_BASE64").isNullOrBlank()) {
        signingConfigs {
            create("rafiqRelease") {
                storeFile = file("rafiq-release.keystore")
                storePassword = System.getenv("RELEASE_STORE_PASSWORD") ?: ""
                keyAlias = System.getenv("RELEASE_KEY_ALIAS") ?: "rafiq"
                keyPassword = System.getenv("RELEASE_KEY_PASSWORD") ?: ""
            }
        }
    }
'''
        if 'create("rafiqRelease")' not in text:
            match = re.search(r'\bandroid\s*\{', text)
            if match is None:
                raise RuntimeError("android { block not found while configuring release signing")
            end = match.end()
            text = text[:end] + "\n" + block + text[end:]
        old = 'signingConfig = signingConfigs.getByName("debug")'
        new = '''signingConfig = if (!System.getenv("RELEASE_KEYSTORE_BASE64").isNullOrBlank()) {
                signingConfigs.getByName("rafiqRelease")
            } else {
                signingConfigs.getByName("debug")
            }'''
        text = text.replace(old, new)
    else:
        block = '''    if (System.getenv('RELEASE_KEYSTORE_BASE64')) {
        signingConfigs {
            rafiqRelease {
                storeFile file('rafiq-release.keystore')
                storePassword System.getenv('RELEASE_STORE_PASSWORD') ?: ''
                keyAlias System.getenv('RELEASE_KEY_ALIAS') ?: 'rafiq'
                keyPassword System.getenv('RELEASE_KEY_PASSWORD') ?: ''
            }
        }
    }
'''
        if 'rafiqRelease {' not in text:
            match = re.search(r'\bandroid\s*\{', text)
            if match is None:
                raise RuntimeError("android { block not found while configuring release signing")
            end = match.end()
            text = text[:end] + "\n" + block + text[end:]
        old = 'signingConfig signingConfigs.debug'
        new = "signingConfig System.getenv('RELEASE_KEYSTORE_BASE64') ? signingConfigs.rafiqRelease : signingConfigs.debug"
        text = text.replace(old, new)
    return text

def copy_resources() -> None:
    if not RES_SRC.exists():
        print("::warning::{0} not found; launcher icons were not installed".format(RES_SRC))
        return
    count = 0
    for src in sorted(RES_SRC.rglob("*")):
        if not src.is_file():
            continue
        dst = RES_DST / src.relative_to(RES_SRC)
        dst.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(src, dst)
        count += 1
    print("Copied {0} resource files into {1}".format(count, RES_DST))


def main() -> int:
    if not MANIFEST.exists():
        print("::error::{0} not found. Did `flutter create` run?".format(MANIFEST))
        return 1

    original = MANIFEST.read_text(encoding="utf-8")
    patched = patch_manifest(original)
    if patched != original:
        MANIFEST.write_text(patched, encoding="utf-8")
        print("Manifest patched: permissions + largeHeap")
    else:
        print("Manifest already patched")

    found_gradle = False
    for path in GRADLE_FILES:
        if not path.exists():
            continue
        found_gradle = True
        text = path.read_text(encoding="utf-8")
        new_text, changes = patch_gradle(text, path.suffix == ".kts")
        new_text, desugar_changed = enable_desugaring(new_text, path.suffix == ".kts")
        new_text = configure_release_signing(new_text, path.suffix == ".kts")
        if desugar_changed:
            changes.append("core library desugaring")
        if new_text != text:
            path.write_text(new_text, encoding="utf-8")
            print("----- final {0} -----".format(path))
            print(new_text)
            print("----- end -----")
            print("{0} patched: {1}".format(path, "; ".join(changes)))
        else:
            print("{0}: no change needed".format(path))

    if not found_gradle:
        print("::warning::No android/app/build.gradle(.kts) found; SDK levels were not touched")

    copy_resources()
    return 0


if __name__ == "__main__":
    sys.exit(main())
